import sys; sys.path.insert(0,'/workspace/t')
from run import run
def mk(parts):
    c=[{"name":"a","frames":[{"Type":"headers","data_to_transfered":[[":method","GET"]],"End_Stream":True}],
        "expect":{"method":"GET","target":"/x","host":"h.example"}}]
    return {"seed":"s","definitions":[],"timeout_ms":10,"cases":c,"events":[],
            "channels":[{"name":"c","parts":[{"case":"a","data":p} for p in parts]}]}
def probe(label, parts):
    out = run(mk(parts))
    if 'error' in out: print('%-40s -> INPUT ERROR'%label); return
    ch=out['channels'][0]
    print('%-40s -> err=%s reqs=%d bytes=%d'%(label, ch['error'], len(ch['requests']), ch['bytes']['n']))
head = b"GET /x HTTP/1.1\r\n"
def line(n): return b"X: " + b"a"*(n-5) + b"\r\n"
for extra in (0,1):
    body = b"".join(line(605) for _ in range(108)) + line(68+extra) + b"\r\n"
    total = len(head)+len(body)
    probe('block size %d'%total, [head.decode(), body[:30000].decode(), body[30000:].decode()])
PYEOF
